-- Passage rg9-theme-summary-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('cb146cb0-3216-53e1-887d-2b0f5e020adb', 'rg9-theme-summary-p02', (select id from public.skills where slug = 'read-g9-theme-summary'), null,
        '9-12', $q$Relay of Wings$q$, $q$In March they lift from mountain firs,
a cloud of orange coming loose,
and drift north over fields still brown.
They do not know the way. They go.

By midsummer they are tired and torn.
They lay small eggs on milkweed leaves,
then fold their wings and do not rise.
The journey is not theirs to finish.

The eggs become small striped mouths.
The mouths become green quiet rooms.
The rooms split open into wings,
and daughters fly the second leg.

And then the granddaughters, and theirs,
each one a mile marker in the air,
each one a runner with no finish line,
handing the north to someone new.

Not one of them has seen the firs
and also seen the northern lakes.
Not one has stood at both ends of the road.
No single wing can hold the whole of it.

Yet every fall the last ones turn
and find the mountain they have never seen,
as if the map were folded into them
by all the ones who flew before.

So when I plant a tree I will not
sit beneath, or start a page
that someone else will have to end,
I think of orange coming loose in March.$q$, 'draft')
