  ('cdee7a02-6da1-5d8a-bd50-effad577cb42', null, (select id from public.skills where slug = 'read-g9-theme-summary'), null, 'hard',
   $q$How does Dr. Fenwick's reply develop the theme?$q$, $q$[{"text":"It shows that reporting the error made the data usable and earned trust, since she keeps the samples and asks for his help.","is_correct":true},{"text":"It suggests that real scientists almost never make mistakes in their maps.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It shows that Keoni's mistake did not matter, since she had already noticed the problem.","is_correct":false,"misconception_token":"misreads-detail"},{"text":"It shows that she plans to report the class to the county for careless work.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$It shows that reporting the error made the data usable and earned trust, since she keeps the samples and asks for his help.$q$, $q$She would have thrown out both samples, but his report lets her keep them, and she invites him back. The tempting idea that the mistake did not matter ignores that, without his report, the samples would have been lost.$q$, 'draft', 'c72ddb49-a2f2-590c-bd6d-77bc8f5c0dc1')
