  ('74cb6c29-6f31-5045-b7ca-3f24657bf2cf', null, (select id from public.skills where slug = 'read-g9-word-parts'), null, 'hard',
   $q$The suffix -ous means "full of," and son means "sound." What kind of tone is a "deep, sonorous tone"?$q$, $q$[{"text":"A quick, sharp sound that stops at once","is_correct":false,"misconception_token":"ignores-context"},{"text":"A sour, wrong sound from a misread note","is_correct":false,"misconception_token":"confuses-nearby-details"},{"text":"A thin, light sound that is hard to hear","is_correct":false,"misconception_token":"opposite-meaning"},{"text":"A full, rich sound that carries strongly","is_correct":true}]$q$::jsonb, $q$A full, rich sound that carries strongly$q$, $q$Son plus -ous means "full of sound," and the tone is strong enough that it "made the floor seem to tremble." A thin sound that is hard to hear contradicts that effect.$q$, 'draft', '010113db-f97d-53bd-893b-4116d3ab8a16')
