  ('cbbb0976-6522-5eb8-a9cb-dbe0f78310ec', null, (select id from public.skills where slug = 'read-g10-authors-purpose'), null, 'medium',
   $q$How do the sentences "Those people matter. Yet theories need data..." function in the article?$q$, $q$[{"text":"They explain how professors trained volunteers to take accurate readings in the cold.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"They concede the importance of inventors and professors, then argue that volunteers deserve credit too.","is_correct":true},{"text":"They show that the author has changed his mind and now thinks inventors deserve all the credit.","is_correct":false,"misconception_token":"reverses-viewpoint"},{"text":"They reject the work of inventors and professors as less important than the work of volunteers.","is_correct":false,"misconception_token":"misreads-concession"}]$q$::jsonb, $q$They concede the importance of inventors and professors, then argue that volunteers deserve credit too.$q$, $q$"Those people matter" grants the value of the usual heroes, and "Yet" introduces the counterpoint that their theories depended on volunteers' data. The author adds the volunteers to the story rather than removing the inventors from it.$q$, 'draft', '3afc60df-1469-543f-8804-643b3b3788c0')
