  ('1267e147-72c5-536f-936e-28b9f989f8d5', null, (select id from public.skills where slug = 'read-g10-authors-purpose'), null, 'easy',
   $q$Which statement best expresses the author's point of view?$q$, $q$[{"text":"Students should continue a world language past the requirement because the third year brings real use.","is_correct":true},{"text":"The first two years of a language class are a waste of time and should be shortened or removed.","is_correct":false,"misconception_token":"distorts-claim"},{"text":"Schools should require four years of a world language for every student who wants to graduate.","is_correct":false,"misconception_token":"overstates-claim"},{"text":"Students who dropped their language class after two years made a choice they will never understand.","is_correct":false,"misconception_token":"misreads-tone"}]$q$::jsonb, $q$Students should continue a world language past the requirement because the third year brings real use.$q$, $q$He writes "I think more of you should stay too" and explains that third year is "when you finally start to build." He calls the first two years preparation, not a waste, and he never asks for a new requirement.$q$, 'draft', 'f863236c-afb5-59f4-b253-59d685a12316')
